# FABRIK: Fix Favicon 404 Error
# IBM+++ MCP MCP MCP Standard - Industrial Fabrication Software
# Behebt 404-Fehler für favicon.ico

$ErrorActionPreference = "Stop"

Write-Host "========================================" -ForegroundColor Cyan
Write-Host "FABRIK: FIX FAVICON 404 ERROR" -ForegroundColor Cyan
Write-Host "IBM+++ MCP MCP MCP STANDARD" -ForegroundColor Cyan
Write-Host "========================================" -ForegroundColor Cyan
Write-Host ""

$targetFile = $args[0]
if (-not $targetFile) {
    $targetFile = "MUSIK-PROGRAMME\Gitarren‑Akkord‑Transposer – ohne Build.html"
}

if (-not (Test-Path $targetFile)) {
    Write-Host "FEHLER: $targetFile nicht gefunden!" -ForegroundColor Red
    exit 1
}

Write-Host "[1/4] Lade Datei..." -ForegroundColor Yellow
$content = Get-Content $targetFile -Raw -Encoding UTF8
Write-Host "  ✅ Datei geladen" -ForegroundColor Green

$modified = $false

# Fix 1: Prüfe ob favicon Link vorhanden ist
Write-Host "[2/4] Prüfe favicon Link..." -ForegroundColor Yellow
if ($content -notmatch '<link[^>]*rel\s*=\s*["''](icon|shortcut icon)["'']') {
    # Füge favicon Link hinzu (mit data URI als Fallback)
    $faviconLink = '<link rel="icon" type="image/x-icon" href="data:image/x-icon;base64, URI als Fallback)" />'
    
    if ($content -match '<head>') {
        $content = $content -replace '<head>', "<head>`n  $faviconLink"
        $modified = $true
        Write-Host "  ✅ Favicon Link hinzugefügt (data URI)" -ForegroundColor Green
    } elseif ($content -match '<meta\s+charset') {
        $content = $content -replace '(<meta\s+charset[^>]*>)', "$1`n  $faviconLink"
        $modified = $true
        Write-Host "  ✅ Favicon Link hinzugefügt (data URI)" -ForegroundColor Green
    }
} else {
    Write-Host "  ✅ Favicon Link bereits vorhanden" -ForegroundColor Green
}

# Fix 2: Erstelle favicon.ico im Root (optional)
Write-Host "[3/4] Prüfe favicon.ico im Root..." -ForegroundColor Yellow
$rootDir = Split-Path (Resolve-Path $targetFile) -Parent
$rootDir = Split-Path $rootDir -Parent  # Gehe zum Projekt-Root
$faviconPath = Join-Path $rootDir "favicon.ico"

if (-not (Test-Path $faviconPath)) {
    Write-Host "  ⚠️  favicon.ico nicht im Root gefunden" -ForegroundColor Yellow
    Write-Host "  ℹ️  Favicon wird über data URI geladen (keine Datei erforderlich)" -ForegroundColor Cyan
} else {
    Write-Host "  ✅ favicon.ico im Root gefunden" -ForegroundColor Green
}

# Fix 3: Füge Error-Handling für favicon hinzu
Write-Host "[4/4] Füge Error-Handling für favicon hinzu..." -ForegroundColor Yellow
if ($content -match 'favicon' -and $content -notmatch 'favicon.*onerror') {
    # Füge onerror Handler hinzu, falls favicon Link vorhanden ist
    $content = $content -replace '(<link[^>]*favicon[^>]*>)', '$1 onerror="this.onerror=null; console.warn(''favicon.ico nicht gefunden - optional'');"'
    $modified = $true
    Write-Host "  ✅ Error-Handling für favicon hinzugefügt" -ForegroundColor Green
}

# Speichere Änderungen
if ($modified) {
    Write-Host ""
    Write-Host "[SAVE] Speichere Änderungen..." -ForegroundColor Yellow
    $utf8NoBom = New-Object System.Text.UTF8Encoding $false
    [System.IO.File]::WriteAllText((Resolve-Path $targetFile), $content, $utf8NoBom)
    Write-Host "  ✅ Datei aktualisiert" -ForegroundColor Green
} else {
    Write-Host ""
    Write-Host "  ℹ️  Keine Änderungen erforderlich" -ForegroundColor Cyan
}

Write-Host ""
Write-Host "========================================" -ForegroundColor Cyan
Write-Host "[OK] FAVICON 404 FIX ABGESCHLOSSEN" -ForegroundColor Green
Write-Host "========================================" -ForegroundColor Cyan
Write-Host ""
Write-Host "T,.&T,,.&T,,,.].T,,,,.(C)(R).T,,.} - TEL1.NL - Together Systems" -ForegroundColor Green

